(async () => {
  fs.writeFileSync(htmlPath, html.replace('font:10pt/1.4', 'font:9.5pt/1.4').replace('padding:3.2mm 0', 'padding:2.5mm 0').replace('padding:2.8mm 0', 'padding:2.1mm 0'));
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1000, height: 1200 }, deviceScaleFactor: 1 });
  await page.goto('file://' + htmlPath);
  await page.evaluate(() => document.fonts.ready);
  await page.emulateMedia({ media: 'print' });
  const overflow = await page.evaluate(() => Array.from(document.querySelectorAll('.sheet')).flatMap((sheet,index) => {
    const footer = sheet.querySelector('footer').getBoundingClientRect();
    const children = Array.from(sheet.children).filter(el => el.tagName !== 'FOOTER');
    const bottom = Math.max(...children.map(el => el.getBoundingClientRect().bottom));
    return bottom > footer.top - 10 ? [{ page:index+1, contentBottom:bottom, footerTop:footer.top }] : [];
  }));
  if (overflow.length) {
    await browser.close();
    throw new Error('Pages overflow: ' + JSON.stringify(overflow));
  }
  await page.emulateMedia({ media: 'print' });
  await page.pdf({ path: output, format: 'A4', printBackground: true, preferCSSPageSize: true, tagged: true, outline: true });
  await page.locator('.sheet').nth(2).screenshot({ path: '/tmp/lc-button-guide-preview.png' });
  await page.locator('.sheet').nth(0).screenshot({ path: '/tmp/lc-button-guide-cover.png' });
  const buffer = fs.readFileSync(output);
  const actualPages = (buffer.toString('latin1').match(/\/Type\s*\/Page\b/g) || []).length;
  if (actualPages !== pages.length + 3) throw new Error(`Expected ${pages.length+3} PDF pages, got ${actualPages}`);
  await browser.close();
  if (process.argv.includes('--desktop-copy')) {
    fs.copyFileSync(output, '/Users/steveforeman/Desktop/Living Culture Staff Reference.pdf');
    fs.copyFileSync(htmlPath, '/Users/steveforeman/Desktop/Living Culture Staff Reference.html');
  }
  console.log(JSON.stringify({ output, htmlPath, pages: actualPages, bytes: buffer.length, controlGroups: pages.reduce((sum,p) => sum+p[2].length,0), overflow: overflow.length }, null, 2));
})().catch(error => { console.error(error); process.exitCode = 1; });
